def read_number(n: int) -> str:
    digits = "일이삼사오육칠팔구"

    def group(g: int) -> str:
        # Reads a number from 1 to 9999 in Sino-Korean.
        s = ""
        for val, unit in ((1000, "천"), (100, "백"), (10, "십")):
            d = (g // val) % 10
            if d:
                s += unit if d == 1 else digits[d - 1] + unit
        ones = g % 10
        if ones:
            s += digits[ones - 1]
        return s

    if n == 0:
        return "영"

    result = ""
    eok = n // 100000000
    man = (n // 10000) % 10000
    rest = n % 10000

    if eok:
        result += group(eok) + "억"
    if man:
        result += "만" if man == 1 else group(man) + "만"
    if rest:
        result += group(rest)
    return result
